-- FileMaker migration target schema: MBA convention + MBS school + bulk e-mail, one SQLite database (web app demo)
-- Written from the table, graph and value-list explorer CSVs. Base tables are generated by gen04.py from one
-- disposition map, then reviewed; system tables, child tables, views and seeds are written by hand.
--
-- Evidence:
--   source implementation(s): MBA.fmp12, MBS.fmp12, MBS_SendMail.fmp12 (DDR of 2026-11-13, FileMaker 26.0.3).
--     sci_admin is outside the export and out of scope (D-04).
--   objects: objects/index.tsv (806 rows; 43 base tables, 1,079 fields, 57 relationships, 36 value lists)
--   source data profile: none. No FileMaker data is migrated; a seed tool writes synthetic data (D-02).
--   target database/version: SQLite 3.40+ through rusqlite (bundled). PRAGMA journal_mode = WAL and
--     PRAGMA foreign_keys = ON on every connection (stack decision, see decisions.md; 02 confirms).
--   timezone/DST decision: dates are ISO 8601 text (YYYY-MM-DD); times HH:MM[:SS]; timestamps are local civil time
--     of Puerto Rico, 'YYYY-MM-DD HH:MM:SS', no offset (America/Puerto_Rico has no DST; D-67 inference, demo).
--   unresolved blockers: none. Open decisions OD-04-01 .. OD-04-05 are listed at the end.
--
-- Conventions (product decisions for the demo, 2026-11-21; decisions.md and D-ids):
--   * One database, three modules: convention (MBA), school (MBS), bulk e-mail (MBS_SendMail) (D-01).
--     The e-mail tables take the prefix mail_. people and students stay separate tables. One affiliates table.
--   * Names: snake_case of the FileMaker name (SKILL.md rule). Accented letters lose the accent, Ñ becomes n,
--     '#' becomes num (COMPAÑIA -> compania, Account # -> account_num). A field named with an SQL keyword is renamed
--     (order -> sort_order, default -> is_default, from -> from_email, to -> to_addrs). The full source-to-target
--     register is 04_database_schema_appendix.md.
--   * Keys: every source table keyed by a Get(UUID) auto-enter keeps that field as `uuid TEXT PRIMARY KEY`; the app
--     generates UUID v4 text. Tables with no key (sponsor, professors) get a new uuid key (D-11). MBS serial `id`
--     fields that a layout or script shows become `serial` (the name id would read as the key); unused ones are dropped.
--   * Foreign keys: enforced from day one. Keys are unique by construction and no legacy rows are loaded (D-02),
--     so the 40 needs-profile relationships become real foreign keys. Name-match links (COMPAÑIA = Socio,
--     NOMBRE, CURSO, event_key) become key links (D-11).
--   * ON DELETE: CASCADE only where FileMaker has "delete related" on and the child carries no money (registration
--     items and guests, calendar dates, certification requirements, package items, e-mails of a batch, event items,
--     sponsor and billing rows of an event). Rows that carry money are cancelled or voided, not deleted (D-09).
--   * Money: INTEGER cents (USD). Arithmetic is integer; values are converted only at the HTML edge. Every money
--     column carries the comment "money: integer cents".
--   * Calculated fields, summary fields, recalc flags (sase_update, update, need_update, update_counts), stored
--     ExecuteSQL snapshots and display concatenations get no column. Live views below or app code compute them
--     (D-03, D-04). Looked-up prices are stored on creation, because the source copies them once (D-14).
--   * Globals get no column: session state becomes request or form state, settings go to app_settings (D-33).
--   * Repeating fields become child rows (D-26): calendar_short_course_dates, student_certification_interests.
--   * Containers become stored_files rows (file on disk under the app data folder). Plug-in installers are dropped.
--   * Value-list enums that a rule depends on carry a CHECK; this strengthens the source, which validates none of
--     them (demo, no legacy data, D-02). All custom value lists are also seeded in value_list_items for the forms.
--   * "Not empty" source validation is enforced in the command layer (07); NOT NULL is added only on keys, foreign
--     keys of child rows and names the app cannot work without.
--   * No SSN column (D-06). No SMTP or plug-in secret has a column or a setting (D-05). Mail goes through Resend
--     when RESEND_API_KEY is set; without it every message goes to mail_outbox and the app shows it (D-05).
--   * Sign-in is local: users + sessions, argon2id hashes, server session cookie, CSRF token (D-50).

PRAGMA foreign_keys = ON;

BEGIN;

-- ---------------------------------------------------------------------------
-- Source-to-target mapping register: 04_database_schema_appendix.md
-- (one row per base table, field, relationship and value list)
-- ---------------------------------------------------------------------------

-- ---------------------------------------------------------------------------
-- System tables (target-platform requirement; AUTH and SYS domains)
-- ---------------------------------------------------------------------------

-- Key/value settings. Replaces globals tables, hard-coded constants and hard-coded signers (D-18, D-25, D-33).
CREATE TABLE app_settings (
  key TEXT PRIMARY KEY NOT NULL,
  value TEXT,
  description TEXT,
  modified_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%S','now','localtime')),
  modified_by TEXT
);

-- Custom value lists (value_lists register in the appendix). Field-based lists are queries, not rows.
CREATE TABLE value_list_items (
  list TEXT NOT NULL,             -- FileMaker value-list name
  value TEXT NOT NULL,
  sort_order INTEGER NOT NULL,
  active INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0, 1)),
  PRIMARY KEY (list, value)
);

-- Uploaded files. Replaces container fields (events.pdf, sponsor.logo, billing.file, batches.attachment, MBS logo).
CREATE TABLE stored_files (
  uuid TEXT PRIMARY KEY NOT NULL,
  filename TEXT NOT NULL,
  mime_type TEXT NOT NULL,
  size_bytes INTEGER NOT NULL,
  sha256 TEXT NOT NULL,
  storage_path TEXT NOT NULL,     -- relative to the app data folder
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%S','now','localtime')),
  created_by TEXT
);

-- Editable letter, certificate and policy texts with merge fields (D-18). Print pages render them (06).
CREATE TABLE document_templates (
  code TEXT PRIMARY KEY NOT NULL, -- stable id used by the print routes, for example 'mba.confirmation_letter'
  module TEXT NOT NULL CHECK (module IN ('convention', 'school', 'mail')),
  title TEXT NOT NULL,
  body_html TEXT NOT NULL,        -- HTML with {{merge_field}} tokens
  source_layout TEXT,             -- objects/<file>/layouts/<id>-<name>.txt the text came from
  modified_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%S','now','localtime')),
  modified_by TEXT
);

-- Local sign-in (D-50). Role values map to ROLE-ADMIN and ROLE-STAFF in 08_auth_roles.md.
CREATE TABLE users (
  id INTEGER PRIMARY KEY,
  username TEXT NOT NULL UNIQUE COLLATE NOCASE, -- case-insensitive, as FileMaker account names (D-84)
  display_name TEXT NOT NULL,
  email TEXT,
  password_hash TEXT NOT NULL,    -- argon2id PHC string; never a plain password
  role TEXT NOT NULL CHECK (role IN ('admin', 'staff')),
  active INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0, 1)),
  failed_login_count INTEGER NOT NULL DEFAULT 0,
  locked_until TEXT,
  last_login_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%S','now','localtime')),
  modified_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%S','now','localtime'))
);

-- Server sessions. The cookie holds a random token; the table holds its SHA-256 (D-50, AP-01).
CREATE TABLE sessions (
  token_hash TEXT PRIMARY KEY NOT NULL,
  user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  csrf_token TEXT NOT NULL,
  created_at TEXT NOT NULL,
  last_seen_at TEXT NOT NULL,
  expires_at TEXT NOT NULL,
  ip TEXT,
  user_agent TEXT
);

-- Audit trail for deletes, voids, cancellations, bulk operations, sign-in events and role changes (08).
CREATE TABLE audit_log (
  id INTEGER PRIMARY KEY,
  at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%S','now','localtime')),
  user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,
  action TEXT NOT NULL,           -- for example 'payment.void', 'student.delete', 'mail.send_batch', 'auth.login_failed'
  entity TEXT,
  entity_uuid TEXT,
  detail TEXT                     -- JSON
);

-- ---------------------------------------------------------------------------
-- Base tables (generated from the disposition map; source object file and field id on each column)
-- ---------------------------------------------------------------------------

-- Source: objects/MBS.fmp12/tables/130-affiliates.txt
-- Domain: AFF. One shared member-company list for both modules (D-01).
-- Audit columns replace the log_* auto-enter fields.
CREATE TABLE affiliates (
  uuid TEXT PRIMARY KEY NOT NULL, -- #31 Get(UUID) auto-enter; parent side of r1
  account_num INTEGER, -- #1
  socio TEXT NOT NULL, -- #2 member company name; value list affiliates_by_name
  other_name TEXT, -- #3
  address TEXT, -- #4
  city TEXT, -- #5
  state_zip TEXT, -- #6
  telephone TEXT, -- #7
  fax TEXT, -- #8
  miembro TEXT, -- #11 membership class; value list affiliates_membresia (REGULAR, ASOCIADO, CORRESPONSAL)
  tipo_de_negocio TEXT, -- #12
  address1 TEXT, -- #14
  e_mail TEXT, -- #19
  zip TEXT, -- #36
  telephone_1 TEXT, -- #44
  customer_e_mail TEXT, -- #45
  cust_type TEXT, -- #46 membership status; value list activo_inactivo; 'ACTIVO' makes students affiliates (BR-AFF-01)
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%S','now','localtime')),
  created_by TEXT,
  modified_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%S','now','localtime')),
  modified_by TEXT
);

-- Source: objects/MBS.fmp12/tables/131-students.txt
-- Domain: STU. people and students stay separate tables (D-01). No SSN column (D-06).
-- Audit columns replace the log_* auto-enter fields.
CREATE TABLE students (
  uuid TEXT PRIMARY KEY NOT NULL, -- #2 Get(UUID) auto-enter; parent side of r2, r18, r25, r30
  member_uuid TEXT REFERENCES affiliates(uuid) ON DELETE SET NULL, -- #35 r1; set by key, not by name match (D-11)
  compania TEXT, -- #12 company name as typed; set from affiliates.socio when an affiliate is picked (BR-STU-02)
  dir_residencial TEXT, -- #13
  dir_trabajo TEXT, -- #14
  email TEXT, -- #15
  fax TEXT, -- #16
  nombre TEXT NOT NULL, -- #17 full name; strengthened to NOT NULL (no legacy data, D-02)
  residencial_2 TEXT, -- #18
  telefono_r TEXT, -- #20
  telefono_t TEXT, -- #21
  email_work TEXT, -- #26
  phone_mobile TEXT, -- #27
  company_position TEXT, -- #28
  company_department TEXT, -- #40
  home_city TEXT, -- #30
  home_state TEXT, -- #31
  home_zip TEXT, -- #32
  emergency_contact TEXT, -- #36
  emergency_phone TEXT, -- #37
  emergency_contact_relationship TEXT, -- #38
  work_experience TEXT, -- #39
  nmls TEXT, -- #42 NMLS id (CSBS export, BR-RPT-06)
  student_id TEXT, -- #43 student number shown on transcripts
  notes TEXT, -- #64
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%S','now','localtime')),
  created_by TEXT,
  modified_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%S','now','localtime')),
  modified_by TEXT
);

