-- Source: objects/MBS.fmp12/tables/150-professors.txt
-- Domain: CRS. Calendar rows reference professors by key, not by name (D-11).
-- Audit columns: target-platform requirement (source table has no log fields).
CREATE TABLE professors (
  uuid TEXT PRIMARY KEY NOT NULL, -- new key: the source table has none (D-11)
  name TEXT NOT NULL UNIQUE, -- #1
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%S','now','localtime')),
  created_by TEXT,
  modified_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%S','now','localtime')),
  modified_by TEXT
);

-- Source: objects/MBS.fmp12/tables/141-calendar_course.txt
-- Domain: CRS. One row per course offering. Dates live in calendar_course_dates.
-- Audit columns replace the log_* auto-enter fields.
CREATE TABLE calendar_course (
  uuid TEXT PRIMARY KEY NOT NULL, -- #2 parent side of r10, r11
  serial INTEGER, -- #3 calendar number shown on Cursos Especializados
  course_uuid TEXT NOT NULL REFERENCES courses(uuid), -- #14 r8
  status TEXT NOT NULL DEFAULT 'Pendiente' CHECK (status IN ('Pendiente', 'Confirmado', 'Completado', 'Cancelado')), -- #12 value list course_statuses
  semester TEXT, -- #27 Febrero / Septiembre; auto-enter inactive in source, typed by hand
  cost_member INTEGER, -- money: integer cents (#19 copied from courses on creation, BR-CRS-02)
  cost_individual INTEGER, -- money: integer cents (#20 copied from courses on creation, BR-CRS-02)
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%S','now','localtime')),
  created_by TEXT,
  modified_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%S','now','localtime')),
  modified_by TEXT
);

