  status TEXT NOT NULL DEFAULT 'Día de Clase' CHECK (status IN ('Día de Clase', 'Día de Fiesta')), -- #14 value list course_calendar_day_type (D-28)
  note TEXT, -- #15
  professor_uuid TEXT REFERENCES professors(uuid), -- #16 was the professor name (D-11)
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%S','now','localtime')),
  created_by TEXT,
  modified_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%S','now','localtime')),
  modified_by TEXT
);

