-- ---------------------------------------------------------------------------
-- Views (live values that FileMaker stored or computed; D-03). Rule ids are in 07_business_logic.md.
-- ---------------------------------------------------------------------------

-- BR-REG-05, BR-REG-06, BR-REG-07. Source: objects/MBA.fmp12/tables/135-registration_items.txt #16 total,
-- #28 is_hotel, #29 is_seating, #55 from_package.
CREATE VIEW v_registration_item_lines AS
SELECT ri.uuid,
       ri.registration_uuid,
       ri.event_item_uuid,
       ei.event_uuid,
       ei.name AS event_item_name,
       ei.type AS event_type,
       ei.date_start, ei.date_end, ei.time_start, ei.time_end,
       CASE WHEN ei.type = 'Hotel' THEN 1 ELSE 0 END AS is_hotel,
       CASE WHEN ei.type IN ('Cena', 'Almuerzo', 'Seminario', 'Desayuno') THEN 1 ELSE 0 END AS is_seating,
       CASE WHEN ri.package_item_uuid IS NOT NULL THEN 1 ELSE 0 END AS from_package,
       ri.ticket_qty,
       ri.price,
       CASE WHEN ri.no_charge = 1 OR ri.package_item_uuid IS NOT NULL THEN 0
            ELSE ri.ticket_qty * ri.price END AS total            -- money: integer cents
FROM registration_items ri
JOIN event_items ei ON ei.uuid = ri.event_item_uuid;

-- BR-EVT-05. Source: objects/MBA.fmp12/tables/136-packages.txt #13 price (price_override, else the sum of the
-- active package items' totals).
CREATE VIEW v_package_price AS
SELECT p.uuid AS package_uuid,
       p.event_uuid,
       COALESCE(p.price_override,
                (SELECT COALESCE(SUM(pi.price * pi.ticket_qty), 0)
                   FROM package_items pi
                  WHERE pi.package_uuid = p.uuid AND pi.active = 1)) AS price   -- money: integer cents
FROM packages p;

-- BR-REG-04, BR-REG-08, BR-REG-09. Source: objects/MBA.fmp12/tables/133-registration.txt #14 total, #19 payment_total,
-- #29 balance, #17 guests_count, #47 has_hotel, #50 is_convencionista, #23/#24 arrival and departure dates.
CREATE VIEW v_registration_totals AS
WITH base AS (
  SELECT r.uuid AS registration_uuid,
         r.event_uuid,
         r.person_uuid,
         r.status,
         (SELECT COUNT(*) FROM registration_guests g WHERE g.registration_uuid = r.uuid) AS guests_count,
         CASE WHEN r.package_uuid IS NOT NULL
              THEN COALESCE((SELECT vp.price FROM v_package_price vp WHERE vp.package_uuid = r.package_uuid), 0)
                 + COALESCE((SELECT SUM(l.total) FROM v_registration_item_lines l
                              WHERE l.registration_uuid = r.uuid AND l.from_package = 0), 0)
              ELSE COALESCE((SELECT SUM(l.total) FROM v_registration_item_lines l
                              WHERE l.registration_uuid = r.uuid), 0)
         END AS total,
         COALESCE((SELECT SUM(p.payment) FROM payments p
                    WHERE p.registration_uuid = r.uuid AND p.voided_at IS NULL), 0) AS payment_total,
         EXISTS (SELECT 1 FROM v_registration_item_lines l
                  WHERE l.registration_uuid = r.uuid AND l.is_hotel = 1) AS has_hotel,
         (SELECT MIN(l.date_start) FROM v_registration_item_lines l
           WHERE l.registration_uuid = r.uuid AND l.is_hotel = 1) AS arrival_date,
         (SELECT MAX(l.date_end) FROM v_registration_item_lines l
           WHERE l.registration_uuid = r.uuid AND l.is_hotel = 1) AS departure_date
  FROM registration r
)
SELECT base.*,
       total - payment_total AS balance,                          -- money: integer cents
       CASE WHEN has_hotel THEN 'Convencionista' ELSE 'Participante' END AS registration_type
FROM base;

-- BR-EVT-04. Source: objects/MBA.fmp12/tables/131-events.txt #21 count_registrations, #22 count_guests,
-- #23 count_total, #25 total, #26 payments, #27 balance, #13 price, #29-#31 sponsor sums.
CREATE VIEW v_event_totals AS
SELECT e.uuid AS event_uuid,
       (SELECT COUNT(*) FROM registration r WHERE r.event_uuid = e.uuid) AS count_registrations,
       (SELECT COALESCE(SUM(t.guests_count), 0) FROM v_registration_totals t WHERE t.event_uuid = e.uuid) AS count_guests,
       (SELECT COUNT(*) FROM registration r WHERE r.event_uuid = e.uuid)
     + (SELECT COALESCE(SUM(t.guests_count), 0) FROM v_registration_totals t WHERE t.event_uuid = e.uuid) AS count_total,
       (SELECT COALESCE(SUM(t.total), 0) FROM v_registration_totals t WHERE t.event_uuid = e.uuid) AS total,
       (SELECT COALESCE(SUM(t.payment_total), 0) FROM v_registration_totals t WHERE t.event_uuid = e.uuid) AS payments,
       (SELECT COALESCE(SUM(t.balance), 0) FROM v_registration_totals t WHERE t.event_uuid = e.uuid) AS balance,
       (SELECT COALESCE(SUM(ei.price), 0) FROM event_items ei WHERE ei.event_uuid = e.uuid) AS price,
       (SELECT COALESCE(SUM(s.promised), 0) FROM sponsor s WHERE s.event_uuid = e.uuid) AS sponsor_promised,
       (SELECT COALESCE(SUM(s.amount_received), 0) FROM sponsor s WHERE s.event_uuid = e.uuid) AS sponsor_received,
       (SELECT COALESCE(SUM(s.promised), 0) + COALESCE(SUM(s.amount_received), 0)
          FROM sponsor s WHERE s.event_uuid = e.uuid) AS sponsor_total
FROM events e;

-- BR-ENR-02, BR-ENR-04, BR-ENR-05. Source: objects/MBS.fmp12/tables/139-enrollments_course.txt #11 BALANCE,
-- #28 NOTA, #82 is_passed; course date and status from the calendar (#78 course_date, #74 course_status).
CREATE VIEW v_enrollments_course_lines AS
SELECT ec.*,
       COALESCE(ec.costo, 0) - ec.pago AS balance,                 -- money: integer cents
       CASE WHEN ec.puntuacion IS NULL THEN NULL
            WHEN ec.puntuacion >= 90 THEN 'A' WHEN ec.puntuacion >= 80 THEN 'B'
            WHEN ec.puntuacion >= 70 THEN 'C' WHEN ec.puntuacion >= 60 THEN 'D' ELSE 'F' END AS nota,
       CASE WHEN ec.puntuacion > 69 THEN 1 ELSE 0 END AS is_passed,
       (SELECT MIN(d.date) FROM calendar_course_dates d WHERE d.calendar_course_uuid = ec.course_calendar_uuid) AS course_date,
       cc.status AS course_status,
       c.course, c.credits, c.hours
FROM enrollments_course ec
JOIN courses c ON c.uuid = ec.course_uuid
LEFT JOIN calendar_course cc ON cc.uuid = ec.course_calendar_uuid;

-- BR-CRS-01, BR-CRS-03, BR-RPT-03. Source: objects/MBS.fmp12/tables/141-calendar_course.txt #24 is_active,
-- #13 date, #16 quorum, #17 enrollments, #18 needed, #41 count_baja, sase_* revenue fields;
-- objects/MBS.fmp12/custom-functions/13-sql.enrollmentsCount.txt and sql.enrollmentsRevenue.
CREATE VIEW v_calendar_course_summary AS
SELECT cc.uuid AS calendar_course_uuid,
       cc.course_uuid,
       cc.status,
       CASE WHEN cc.status IN ('Pendiente', 'Confirmado') THEN 1 ELSE 0 END AS is_active,
       (SELECT MIN(d.date) FROM calendar_course_dates d WHERE d.calendar_course_uuid = cc.uuid) AS first_date,
       c.quorum,
       (SELECT COUNT(*) FROM enrollments_course e WHERE e.course_calendar_uuid = cc.uuid) AS enrollments,
       c.quorum - (SELECT COUNT(*) FROM enrollments_course e WHERE e.course_calendar_uuid = cc.uuid) AS needed,
       (SELECT COUNT(*) FROM enrollments_course e WHERE e.course_calendar_uuid = cc.uuid AND lower(e.status) = 'activo') AS count_activo,
       (SELECT COUNT(*) FROM enrollments_course e WHERE e.course_calendar_uuid = cc.uuid AND lower(e.status) = 'baja') AS count_baja,
       (SELECT COALESCE(SUM(e.pago), 0) FROM enrollments_course e
         WHERE e.course_calendar_uuid = cc.uuid AND e.costeado_por = 'INDIVIDUAL') AS revenue_individual,
       (SELECT COALESCE(SUM(e.pago), 0) FROM enrollments_course e
         WHERE e.course_calendar_uuid = cc.uuid AND e.costeado_por = 'COMPAÑIA') AS revenue_member,
       (SELECT COALESCE(SUM(e.pago), 0) FROM enrollments_course e WHERE e.course_calendar_uuid = cc.uuid) AS revenue_total
FROM calendar_course cc
JOIN courses c ON c.uuid = cc.course_uuid;

-- BR-CRS-01, BR-CRS-03. Source: objects/MBS.fmp12/tables/143-calendar_short_course.txt #17 enrollments, #18 needed, #24 is_active.
CREATE VIEW v_calendar_short_course_summary AS
SELECT cs.uuid AS calendar_short_course_uuid,
       cs.short_course_uuid,
       cs.status,
       CASE WHEN cs.status IN ('Pendiente', 'Confirmado') THEN 1 ELSE 0 END AS is_active,
       (SELECT MIN(d.date) FROM calendar_short_course_dates d WHERE d.calendar_short_course_uuid = cs.uuid) AS first_date,
       cs.quorum,
       (SELECT COUNT(*) FROM enrollments_short_course e WHERE e.short_course_calendar_uuid = cs.uuid) AS enrollments,
       cs.quorum - (SELECT COUNT(*) FROM enrollments_short_course e WHERE e.short_course_calendar_uuid = cs.uuid) AS needed,
       (SELECT COALESCE(SUM(e.pago), 0) FROM enrollments_short_course e WHERE e.short_course_calendar_uuid = cs.uuid) AS revenue_total
FROM calendar_short_course cs;

-- BR-CRS-01, BR-CRS-03. Source: objects/MBS.fmp12/tables/144-calendar_seminar.txt #17 enrollments, #18 needed, #24 is_active.
CREATE VIEW v_calendar_seminar_summary AS
SELECT cs.uuid AS calendar_seminar_uuid,
       cs.seminar_uuid,
       cs.status,
       cs.date,
       CASE WHEN cs.status IN ('Pendiente', 'Confirmado') THEN 1 ELSE 0 END AS is_active,
       cs.quorum,
       (SELECT COUNT(*) FROM enrollments_seminars e WHERE e.seminar_calendar_uuid = cs.uuid) AS enrollments,
       cs.quorum - (SELECT COUNT(*) FROM enrollments_seminars e WHERE e.seminar_calendar_uuid = cs.uuid) AS needed,
       (SELECT COALESCE(SUM(e.pago), 0) FROM enrollments_seminars e WHERE e.seminar_calendar_uuid = cs.uuid) AS revenue_total
FROM calendar_seminar cs;

-- BR-AFF-01, BR-STU-03, BR-STU-06. Source: objects/MBS.fmp12/tables/131-students.txt #63 is_affiliate,
-- #49 average_points, #50 total_credits, #51 total_hours, #67 last_course_date, #68 last_course;
-- objects/MBS.fmp12/scripts/21-sase.updateStudentRecord.txt (ACTIVO when a confirmed course enrollment exists).
CREATE VIEW v_student_academic AS
SELECT s.uuid AS student_uuid,
       CASE WHEN a.cust_type = 'ACTIVO' THEN 1 ELSE 0 END AS is_affiliate,
       CASE WHEN EXISTS (SELECT 1 FROM enrollments_course e JOIN calendar_course cc ON cc.uuid = e.course_calendar_uuid
                          WHERE e.student_uuid = s.uuid AND cc.status = 'Confirmado') THEN 1 ELSE 0 END AS is_active,
       CASE WHEN EXISTS (SELECT 1 FROM enrollments_course e JOIN calendar_course cc ON cc.uuid = e.course_calendar_uuid
                          WHERE e.student_uuid = s.uuid AND cc.status = 'Confirmado') THEN 'ACTIVO' ELSE 'INACTIVO' END AS status,
       (SELECT ROUND(AVG(e.puntuacion)) FROM enrollments_course e WHERE e.student_uuid = s.uuid AND e.puntuacion > 69) AS average_points,
       (SELECT COALESCE(SUM(c.credits), 0) FROM enrollments_course e JOIN courses c ON c.uuid = e.course_uuid
         WHERE e.student_uuid = s.uuid AND e.puntuacion > 69) AS total_credits,
       (SELECT COALESCE(SUM(c.hours), 0) FROM enrollments_course e JOIN courses c ON c.uuid = e.course_uuid
         WHERE e.student_uuid = s.uuid AND e.puntuacion > 69) AS total_hours,
       (SELECT MAX(l.course_date) FROM v_enrollments_course_lines l WHERE l.student_uuid = s.uuid) AS last_course_date
FROM students s
LEFT JOIN affiliates a ON a.uuid = s.member_uuid;

-- BR-CRT-02, BR-CRT-03, BR-CRT-04. Source: objects/MBS.fmp12/tables/146-student_certifications.txt #22 total,
-- #21 completed, #24 left, #28 average_points, #30 total_credits, #31 total_hours, #25 is_graduated, #42 graduation_year;
-- objects/MBS.fmp12/relationships/27-student_certifications_student_certification_enrollments.txt.
-- completed counts distinct passed required courses (changed from as-written: the source counts enrollments, D-31).
CREATE VIEW v_student_certification_progress AS
WITH passed AS (
  SELECT sc.uuid AS student_certification_uuid, e.course_uuid, e.puntuacion, c.credits, c.hours
  FROM student_certifications sc
  JOIN enrollments_course e ON e.student_uuid = sc.student_uuid AND e.puntuacion > 69
  JOIN certification_requirements cr ON cr.course_uuid = e.course_uuid
                                    AND cr.certification_uuid = sc.certification_uuid
                                    AND cr.type = 'Requisito'
  JOIN courses c ON c.uuid = e.course_uuid
),
agg AS (
  SELECT sc.uuid, sc.student_uuid, sc.certification_uuid, sc.graduation_date,
         (SELECT COUNT(*) FROM certification_requirements cr
           WHERE cr.certification_uuid = sc.certification_uuid AND cr.type = 'Requisito')
           + ce.number_of_required_electives AS total,
         (SELECT COUNT(DISTINCT p.course_uuid) FROM passed p WHERE p.student_certification_uuid = sc.uuid) AS completed,
         (SELECT ROUND(AVG(p.puntuacion)) FROM passed p WHERE p.student_certification_uuid = sc.uuid) AS average_points,
         (SELECT COALESCE(SUM(p.credits), 0) FROM passed p WHERE p.student_certification_uuid = sc.uuid) AS total_credits,
         (SELECT COALESCE(SUM(p.hours), 0) FROM passed p WHERE p.student_certification_uuid = sc.uuid) AS total_hours
  FROM student_certifications sc
  JOIN certifications ce ON ce.uuid = sc.certification_uuid
)
SELECT agg.*,
       MAX(total - completed, 0) AS left_count,
       CASE WHEN graduation_date IS NOT NULL THEN 1 ELSE 0 END AS is_graduated,
       CAST(substr(graduation_date, 1, 4) AS INTEGER) AS graduation_year
FROM agg;

-- BR-MAIL-05. Source: objects/MBS_SendMail.fmp12/tables/132-batches.txt #14 count, #16 count_sent, #17 count_errors.
CREATE VIEW v_mail_batch_counts AS
SELECT b.uuid AS batch_uuid,
       (SELECT COUNT(*) FROM mail_emails m WHERE m.batch_uuid = b.uuid) AS count,
       (SELECT COUNT(*) FROM mail_emails m WHERE m.batch_uuid = b.uuid AND m.sent = 1) AS count_sent,
       (SELECT COUNT(*) FROM mail_emails m WHERE m.batch_uuid = b.uuid AND m.error = 1) AS count_errors
FROM mail_batches b;

